using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MilitaryIssuerAuthorityTests
{
 [Theory][InlineData("site:kofu","person:shingen")][InlineData("site:odawara","person:ujiyasu")][InlineData("site:castle","person:nobunaga")]
 public void DirectRetainerResolvesActualHeadMembershipOfficeLandAndBond(string site,string lord){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:site,role:StartTemplate.Retainer,lord:lord)]);var w=s.DiagnosticSnapshot();var house=w.NewGame!.Start.Factions.Single(f=>f.Head==lord);var p=NewGameMilitaryAuthority.Resolve(w,new(lord),s.PlayerControl,new(house.Id),new(site));Assert.NotNull(p);Assert.True(NewGameMilitaryAuthority.MatchesCurrent(w,p));Assert.Contains(w.Memberships,r=>r.Id==p.Membership&&r.Subject==p.Issuer&&r.Target==p.Owner);Assert.Contains(w.Offices,r=>r.Id==p.Office&&r.Subject==p.Issuer);Assert.Contains(w.LandRights,r=>r.Id==p.Control&&r.Subject==p.Owner&&r.Target==p.Site);Assert.Contains(w.ServiceBonds,r=>r.Id==p.Service&&r.Subject==s.PlayerControl);Assert.Empty(w.Units);Assert.Empty(w.ResourceLots);}
 [Theory][InlineData("person:nobunaga")][InlineData("person:shingen")][InlineData("person:ujiyasu")]
 public void HistoricalHeadHasOwnOfficeBasisWithoutFictionalSelfService(string id){var s=NewGameWorldTests.Session([],id);var w=s.DiagnosticSnapshot();var f=w.NewGame!.Start.Factions.Single(f=>f.Head==id);var p=NewGameMilitaryAuthority.Resolve(w,new(id),new(id),new(f.Id),new(f.Home));Assert.NotNull(p);Assert.Null(p.Service);Assert.DoesNotContain(w.ServiceBonds,r=>r.Subject==new EntityId(id)&&r.Target==new EntityId(id));}
 [Fact]public void SameHouseAndIndirectServiceDoNotDelegateHeadAuthority(){var parent=NewGameWorldTests.Officer("created:superior",StartTemplate.Retainer,"site:kofu","person:shingen");var child=NewGameWorldTests.Officer(role:StartTemplate.Subretainer,site:"site:kofu",lord:parent.Id);var s=NewGameWorldTests.Session([parent,child]);var w=s.DiagnosticSnapshot();var house=new EntityId(w.NewGame!.Start.Factions.Single(f=>f.Head=="person:shingen").Id);Assert.Null(NewGameMilitaryAuthority.Resolve(w,new("person:shingen"),s.PlayerControl,house,new("site:kofu")));Assert.Null(NewGameMilitaryAuthority.Resolve(w,new(parent.Id),s.PlayerControl,house,new("site:kofu")));}
 [Fact]public void RoninRetinueDoesNotGrantHouseGarrisonAuthority(){var p=NewGameWorldTests.Officer(site:"site:kofu");var follower=NewGameWorldTests.Officer("created:follower",StartTemplate.Retainer,"site:kofu",p.Id);var s=NewGameWorldTests.Session([p,follower]);var w=s.DiagnosticSnapshot();var house=new EntityId(w.NewGame!.Start.Factions.Single(f=>f.Head=="person:shingen").Id);Assert.Null(NewGameMilitaryAuthority.Resolve(w,new("person:shingen"),s.PlayerControl,house,new("site:kofu")));Assert.Null(NewGameMilitaryAuthority.Resolve(w,s.PlayerControl,new(follower.Id),house,new("site:kofu")));}
 [Fact]public void NewHeadAndIncorporatedOldHeadUseSettledNewOwner(){var p=NewGameWorldTests.Officer(role:StartTemplate.Daimyo);var setup=NewGameWorldTests.Setup([p],[new(p.Id,"org:authority-test",[p.Site],true)]);var w=NewGameWorld.Create(setup.World,setup.Registered,p.Id);var f=w.NewGame!.Start.Factions.Single(f=>f.Head==p.Id);var basis=NewGameMilitaryAuthority.Resolve(w,w.PlayerControl,w.PlayerControl,new(f.Id),new(f.Home));Assert.NotNull(basis);Assert.Null(NewGameMilitaryAuthority.Resolve(w,new("person:nobunaga"),new("person:nobunaga"),new(f.Id),new(f.Home)));var retained=NewGameMilitaryAuthority.Resolve(w,w.PlayerControl,new("person:nobunaga"),new(f.Id),new(f.Home));Assert.NotNull(retained);Assert.NotNull(retained.Service);Assert.Empty(w.Units);}
 [Theory][InlineData("owner")][InlineData("site")][InlineData("office")][InlineData("control")][InlineData("issuer-life")][InlineData("issuer-location")]
 public void MissingRealAuthorityFactCannotBeReplacedByAffiliation(string variant){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);var w=s.DiagnosticSnapshot();var issuer=new EntityId("person:shingen");var own=new EntityId(w.NewGame!.Start.Factions.Single(f=>f.Head==issuer.Value).Id);var site=new EntityId("site:kofu");if(variant=="owner")own=new(w.NewGame.Start.Factions.Single(f=>f.Head=="person:nobunaga").Id);if(variant=="site")site=new("site:odawara");if(variant=="office")w.Offices=w.Offices.Where(r=>r.Subject!=issuer).ToArray();if(variant=="control")w.LandRights=w.LandRights.Where(r=>r.Target!=site).ToArray();if(variant=="issuer-life")w.Characters=w.Characters.Select(c=>c.Id==issuer?c with{Life=LifeState.Dead}:c).ToArray();if(variant=="issuer-location")w.Locations=w.Locations.Select(l=>l.Actor==issuer?l with{Site=new("site:odawara")}:l).ToArray();Assert.Null(NewGameMilitaryAuthority.Resolve(w,issuer,s.PlayerControl,own,site));}
 [Fact]public void SameSecondServiceEndDoesNotInvalidateEarlierCommittedAuthority(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);var w=s.DiagnosticSnapshot();var issuer=new EntityId("person:shingen");var owner=new EntityId(w.NewGame!.Start.Factions.Single(f=>f.Head==issuer.Value).Id);var site=new EntityId("site:kofu");var card=NewGameService.View(w).Cases.Single();Assert.NotNull(NewGameMilitaryAuthority.Resolve(w,issuer,s.PlayerControl,owner,site));Assert.Equal(ResultCode.Accepted,s.DecideService(new(new("request:release-authority"),CareerAction.RequestRelease,card.Case),s.PlayerControl,s.Revision).Code);NewGameWorldTests.At(s,1);w=s.DiagnosticSnapshot();var end=w.Service!.Events.Single(e=>e.Kind==CareerEventKind.Released);Assert.Null(NewGameMilitaryAuthority.Resolve(w,issuer,s.PlayerControl,owner,site));var before=ContractJson.Copy(w);before.ElapsedSeconds=end.At;before.CommitSequence=end.Revision-1;Assert.True(NewGameService.BoundAt(before,issuer,before.ElapsedSeconds,before.CommitSequence));Assert.NotNull(NewGameMilitaryAuthority.Resolve(before,issuer,s.PlayerControl,owner,site));}
}
